import json
import os
from ansible.plugins.callback import CallbackBase


class CallbackModule(CallbackBase):
    CALLBACK_VERSION=2.0
    CALLBACK_TYPE='aggregate'
    CALLBACK_NAME='native_truth'
    CALLBACK_NEEDS_ENABLED=True

    def emit(self,result,status):
        row={'task':result._task.get_name(),'host':result._host.get_name(),'status':status,
             'changed':bool(result._result.get('changed',False))}
        with open(os.environ['OPSFORGE_NATIVE_AUDIT'],'a') as stream:stream.write(json.dumps(row)+'\n')

    def v2_runner_on_ok(self,result):self.emit(result,'ok')
    def v2_runner_on_failed(self,result,ignore_errors=False):self.emit(result,'failed')
    def v2_runner_on_skipped(self,result):self.emit(result,'skipped')
